scwin.externalResponseFunction = function(value, submissionID) {
    var test = '{"dataList2":[{"col1": "11","col2": "22","col3": "33"}]}';
    //alert("decryptVal : " + test);
    return test;
};
scwin.externalFunction = function(value, submissionID) {
    //alert("암호화할 값:::"+value);
    return value;
    /*
    암호화과정
    var encryptVal = externalEncryptFunction(value);//업체제공 API연
    return encryptVal;
    */
};
scwin.trigger1_onclick = function(e) {
    WebSquare.ModelUtil.executeSubmission("submission1");
};
scwin.checkVal1 = function() {
    return WebSquare.wUnit.getJq('#gridView1_cell_0_0').text() == '11';
}
scwin.checkVal2 = function() {
    return WebSquare.wUnit.getJq('#gridView1_cell_0_1').text() == '22';
}
scwin.checkVal3 = function() {
    return WebSquare.wUnit.getJq('#gridView1_cell_0_2').text() == '33';
}
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 0. config.xml의 submission항목에 설정추가(샘플파일에서 동작할수있게 추가되어 config.xml에서 설정 필요 없음)
    //0. Added setting to submission item in config.xml (no need to set in config.xml because it is added to work in sample file)
    //Verify step 0. <externalHandler value = 'scwin.externalFunction' /> <externalResponseHandler value = 'scwin.externalResponseFunction' />
    //Test step 1. 샘플실행 후 'submission'버튼을 클릭하여 gridView에 복호화된 정상값이 보여지는지 확인
    //1. After running the sample, click the 'submission' button to check whether the decoded normal value is displayed in gridView
    //Verify step 1. The decoded values (11, 22, 33) are displayed normally.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 06-Mar-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
